const body = $input.first()?.json?.body || $input.first()?.json || {};
const age = String(body.age || body.basicInfo?.age || '').trim();
const level = String(body.level || body.basicInfo?.level || '').trim();
if (!age || !level) throw new Error('Missing required fields: age and level.');
const themes = Array.isArray(body.themes) ? body.themes : (Array.isArray(body.basicInfo?.themes) ? body.basicInfo.themes : []);
const themeOther = String(body.themeOther || body.basicInfo?.themeOther || '').trim();
const theme = themes[0] || themeOther || '情绪表达';
const participants = String(body.participants || body.basicInfo?.participants || '').trim();
const duration = String(body.duration || body.basicInfo?.duration || '').trim();
const vocabulary = String(body.vocabulary || body.basicInfo?.vocabulary || '').trim();
const grammar = String(body.grammar || body.basicInfo?.grammar || '').trim();
const materials = Array.isArray(body.materials) ? body.materials : (Array.isArray(body.basicInfo?.materials) ? body.basicInfo.materials : []);
const materialOther = String(body.materialOther || body.basicInfo?.materialOther || '').trim();
const materialText = [...materials, materialOther].filter(Boolean).join('、');
return [{ json: {
  userId: String(body.userId || 'anonymous'),
  age,
  level,
  theme,
  themes,
  participants,
  duration,
  vocabulary,
  grammar,
  materials: materialText,
  topic: theme,
  category: String(body.category || '')
} }];

const request = $('Normalize Request').first().json;
const rag = $input.first().json || {};
const system = '你是专业儿童英语教育专家、幸福力课程设计师和绘本故事编剧。只输出严格 JSON，不要 Markdown。';
const user = `请根据以下学生画像和参考资料，设计一个完整的绘本活动方案。

学生画像:
${JSON.stringify(request, null, 2)}

参考资料:
${rag.context || '无'}

要求:
1. 适合指定年龄段和英语水平。
2. storyContent 要有故事感，描述清楚故事背景、角色和情节走向。
3. englishGoal 要结合 vocabulary 和 grammar（如果用户提供了），否则根据主题自动选择适合的核心词汇和句型。
4. wellbeingGoal 要关注儿童社会情感学习（SEL）。
5. outputGoal 要具体、可操作。
6. materials 列出活动需要的物料。
7. storyTitleEn 和 storyTitleZh 要配对，英文简洁有吸引力。

输出 JSON 形状:
{"storyTitleEn":"English Title","storyTitleZh":"中文标题","storyContent":"故事内容描述","englishGoal":"英文学习目标","wellbeingGoal":"幸福力目标","outputGoal":"产出物目标","materials":"物料列表"}`;
return [{ json: { request, rag, messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] } }];

const request = $('Build LLM Prompt').first().json.request;
const rag = $('Build LLM Prompt').first().json.rag;
const response = $input.first().json || {};
let content = response.choices?.[0]?.message?.content || response.output_text || response.text || '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let plan;
try {
  plan = JSON.parse(content);
} catch (error) {
  const match = content.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('The model did not return parseable JSON.');
  plan = JSON.parse(match[0]);
}
const activityPlan = {
  storyTitleEn: String(plan.storyTitleEn || '').trim(),
  storyTitleZh: String(plan.storyTitleZh || '').trim(),
  storyContent: String(plan.storyContent || '').trim(),
  englishGoal: String(plan.englishGoal || '').trim(),
  wellbeingGoal: String(plan.wellbeingGoal || '').trim(),
  outputGoal: String(plan.outputGoal || '').trim(),
  materials: String(plan.materials || request.materials || '').trim()
};
return [{ json: {
  success: true,
  activityPlan,
  rag: {
    referenceCount: rag.referenceCount || 0,
    references: rag.references || []
  }
} }];
